def migrate_legacy_data(apps, schema_editor):
    db = schema_editor.connection.alias
    Ejercicio = apps.get_model("entrenamientos", "Ejercicio")
    GrupoMuscular = apps.get_model("entrenamientos", "GrupoMuscular")
    Equipamiento = apps.get_model("entrenamientos", "Equipamiento")
    EjercicioEquipamiento = apps.get_model("entrenamientos", "EjercicioEquipamiento")
    RutinaDia = apps.get_model("entrenamientos", "RutinaDia")
    RutinaEjercicio = apps.get_model("entrenamientos", "RutinaEjercicio")
    AsignacionRutina = apps.get_model("entrenamientos", "AsignacionRutina")

    for ejercicio in Ejercicio.objects.using(db).all().iterator():
        nombre_grupo = (ejercicio.grupo_muscular or "").strip() or "Sin clasificar"
        grupo, _ = GrupoMuscular.objects.using(db).get_or_create(
            nombre=nombre_grupo[:80]
        )
        ejercicio.grupo_id = grupo.pk
        ejercicio.save(using=db, update_fields=["grupo"])

        for etiqueta in re.split(r"[,;]", ejercicio.equipo or ""):
            nombre_equipo = etiqueta.strip()
            if not nombre_equipo:
                continue
            equipo, _ = Equipamiento.objects.using(db).get_or_create(
                nombre=nombre_equipo[:80]
            )
            EjercicioEquipamiento.objects.using(db).get_or_create(
                ejercicio_id=ejercicio.pk,
                equipamiento_id=equipo.pk,
            )

    dias_por_rutina = {}
    for fila in RutinaEjercicio.objects.using(db).all().iterator():
        dia = dias_por_rutina.get(fila.rutina_id)
        if dia is None:
            dia, _ = RutinaDia.objects.using(db).get_or_create(
                rutina_id=fila.rutina_id,
                orden=1,
                defaults={"nombre": "Día 1"},
            )
            dias_por_rutina[fila.rutina_id] = dia
        fila.rutina_dia_id = dia.pk
        fila.save(using=db, update_fields=["rutina_dia"])

    AsignacionRutina.objects.using(db).filter(activo=False).update(
        estado="FINALIZADA"
    )

    for nombre in (
        "Pecho", "Espalda", "Bíceps", "Tríceps", "Hombros",
        "Piernas", "Glúteos", "Abdomen",
    ):
        GrupoMuscular.objects.using(db).get_or_create(nombre=nombre)
    for nombre in (
        "Barra", "Mancuernas", "Polea", "Máquina", "Banco", "Peso corporal",
    ):
        Equipamiento.objects.using(db).get_or_create(nombre=nombre)


def restore_legacy_data(apps, schema_editor):
    db = schema_editor.connection.alias
    Ejercicio = apps.get_model("entrenamientos", "Ejercicio")
    EjercicioEquipamiento = apps.get_model("entrenamientos", "EjercicioEquipamiento")
    RutinaEjercicio = apps.get_model("entrenamientos", "RutinaEjercicio")
    AsignacionRutina = apps.get_model("entrenamientos", "AsignacionRutina")

    for ejercicio in Ejercicio.objects.using(db).all().iterator():
        if ejercicio.grupo_id:
            ejercicio.grupo_muscular = ejercicio.grupo.nombre
        equipos = EjercicioEquipamiento.objects.using(db).filter(
            ejercicio_id=ejercicio.pk
        ).select_related("equipamiento")
        ejercicio.equipo = ", ".join(
            relacion.equipamiento.nombre for relacion in equipos
        )
        ejercicio.save(using=db, update_fields=["grupo_muscular", "equipo"])

    for fila in RutinaEjercicio.objects.using(db).select_related("rutina_dia"):
        fila.rutina_id = fila.rutina_dia.rutina_id
        fila.save(using=db, update_fields=["rutina"])

    AsignacionRutina.objects.using(db).filter(estado="FINALIZADA").update(activo=False)


